text = input()
pairs = {')': '(', ']': '[', '}': '{'}
stack = []
balanced = True
for char in text:
    if char in '([{':
        stack.append(char)
    elif char in pairs:
        if not stack or stack.pop() != pairs[char]:
            balanced = False
            break
print(balanced and not stack)

